import {sources} from './comics_catalog_sources.mjs';
import {A,W,E,K,S,common} from './comics_catalog_helpers.mjs';
export const RED={...common('RED','Redemption'),title:'Mass Effect: Redemption',sources:sources.RED,
 scope:'Les quatre numéros de Redemption; pont narratif vers Mass Effect 2, personnages, Omega, poursuite et récupération. Bonus éditoriaux traités comme références, pas comme scènes supplémentaires.',
 summary:'Catalogue de production pour une adaptation centrée sur Liara et Feron. Les faits courts sourcés servent d’ancrages aux propositions originales de recherche, infiltration, entraide ATB et mise en scène.',
 canonNote:'Le Shepard personnalisé doit rester compatible avec les choix du joueur. Les notes de l’auteur emploient « Alignon », alors que le wiki emploie « Alingon » : graphie à comparer au comic et au codex avant livraison.',
 continuity:'Pont entre la disparition de Shepard au début de ME2 et sa reconstruction; ne pas rejouer le DLC du Courtier de l’ombre comme s’il appartenait aux quatre numéros.',
 guard:'Préserver l’absence active de Shepard, la relation Liara/Feron et le raccord vers ME2; les méthodes d’enquête ne changent pas le sort publié des protagonistes.',
 group:'Liara contrôlable; Feron partenaire d’infiltration selon le segment. Miranda et Aria restent des interlocutrices dans ce périmètre.',
 atb:'Duo asymétrique proposé : contrôle de terrain pour Liara et préparation d’accès pour Feron; une réserve d’action peut servir à protéger le partenaire au lieu d’infliger des dégâts.',
 facts:[{key:'SCOPE',name:'Série en quatre numéros',text:'Redemption réunit quatre numéros autour de la recherche menée par Liara.',s:'BOOK'},
 {key:'SHEPARD',name:'Shepard adaptable',text:'Le scénariste explique avoir préservé la compatibilité avec les décisions du joueur concernant Shepard.',s:'AUTHOR1',ref:'Notes de conception de Redemption #1',adapt:'Importer les paramètres de Shepard uniquement pour mentions et portraits autorisés; ne pas imposer sexe, visage ou romance.'},
 {key:'FERON',name:'Duo de recherche',text:'Liara s’allie au drell Feron pour récupérer le corps de Shepard auprès du Courtier de l’ombre.',s:'COMPLETE'},
 {key:'BONUS',name:'Croquis du recueil',text:'La notice du recueil annonce des croquis et un complément de fabrication.',s:'BOOK',adapt:'Créer un inventaire de références à consulter, sans transformer les croquis en scènes coupées attestées.'}],
 actors:[A('LIARA','Liara T’Soni','Liara mène la recherche de Shepard.','BOOK','Héroïne du duo; maîtrise du terrain et questions d’enquête.','Peau bleue, crête asari et manteau de terrain simplifié; accents cyan réservés aux actions.','Garde ouverte, poussée des deux bras, lecture d’un terminal, protection du partenaire.',['Écran de passage','Proposition : dépenser une action pour déplacer un obstacle léger et ouvrir un passage au partenaire; inutile contre une structure fixe.','Contour cyan de l’obstacle et flèche vers la case d’arrivée.']),
 A('FERON','Feron','Feron est le partenaire drell de Liara.','COMPLETE','Soutien furtif; transforme une information en fenêtre de progression.','Tête reptilienne et col haut, couches de vêtement lisibles; motifs précis à vérifier.','Coup d’œil latéral, geste de passe, accroupissement et manipulation discrète.',['Couverture d’identité','Préparer une justification avant un contrôle; consommer cette préparation sur un seul accès, sans rendre tous les gardes passifs.','Icône de laissez-passer barrée dès utilisation.']),
 A('MIRANDA','Miranda Lawson','Miranda intervient dans la relation avec Cerberus.','AUTHOR1','Interlocutrice de mission; présenter ses objectifs sans lui donner une omniscience de gameplay.','Combinaison claire à panneaux sombres, silhouette tenue; costume du numéro à comparer.','Posture droite, main sur interface, demi-tour contrôlé.',null,{cat:'npcs'}),
 A('ARIA','Aria T’Loak','Aria fournit une piste sur Omega.','FERON','Négociation brève, accès à une information, autorité locale.','Silhouette asari angulaire, fauteuil en contre-jour et éclairage violet limité au fond.','Immobilité dominante, inclinaison de tête, geste qui clôt l’entretien.',null,{cat:'npcs'}),
 A('TIM','L’Homme trouble','Une scène avec l’Homme trouble est commentée par le scénariste.','AUTHOR2','Communication distante; exposer une proposition sans la valider moralement par l’interface.','Visage partiellement éclairé dans un cadre holographique sobre.','Regard fixe, déplacement léger de la main, interruption du canal.',null,{cat:'npcs'}),
 A('TAZZIK','Tazzik','Tazzik est un exécutant salarian du Courtier.','TAZZIK','Antagoniste identifiable; pression à distance et obstacle à la récupération.','Silhouette salariane exceptionnellement imposante à contrôler; épaules lisibles, teinte froide.','Visée basse, recul bref, blocage de passage et retournement.',null),
 A('BROKER','Courtier de l’ombre — représentation distante','La recherche vise les opérations du Courtier de l’ombre.','COMPLETE','Présence par relais et informations; ne pas révéler sa forme comme un nouveau combat.','Écran opaque, contour artificiel et fond sombre; aucune identité visible ajoutée.','Interface active, brouillage puis extinction.',null,{cat:'npcs'})],
 worlds:[W('OMEGA','Omega','La recherche de Liara traverse Omega.','AUTHOR2','Hub de pistes sous tension.','Boucle courte entre alcôve de contact, passage marchand et accès industriel.','Une ouverture vers les niveaux inférieurs sert de repère vertical.','Métal usé, lumière orange latérale et profondeur industrielle; sol clair sous les sprites.','Raccords internes originaux entre contact, entretien et docks; pas de carte officielle revendiquée.','Contrôles de passage évitables par préparation; aucune foule décorative agressive par défaut.','Ventilation grave, annonces lointaines inventées et percussion métallique espacée.'),
 W('ALINGON','Alingon / Alignon — graphie à contrôler','Le troisième numéro rejoint une base du Courtier sur un monde perturbant les communications.','AUTHOR3','Faire sentir l’isolement informationnel.','Approche extérieure, sas et espace de relais compartimenté; couloirs courts lisibles.','Antenne isolée et écran de contrôle comme points d’orientation.','Roche sombre, métal mat et arcs lumineux très discrets; brouillage en bord de cadre.','Passage spatial vers la base puis sortie vers hangar; chaque raccord coupe la communication non autorisée.','Une interface ne reçoit un ordre qu’au relais local; le silence radio reste expliqué.','Souffle électrique irrégulier et portes étanches, avec absence calculée de radio.',{note:'Faraway Press écrit Alignon; Fandom écrit Alingon. Les deux graphies sont conservées ici uniquement pour contrôle.'}),
 W('SPACE','Poursuite dans l’espace','Le troisième numéro quitte Omega pour une poursuite spatiale.','AUTHOR3','Intermède de navigation lisible, distinct d’un mode de vol complet.','Rail visuel à embranchements courts avec fenêtre de manœuvre et écran de cap.','Balise de destination toujours visible, obstacles en silhouettes.','Astéroïdes mats et contraste faible du ciel; vaisseau du duo traité en sprite orientable.','Départ d’Omega, poursuite puis arrivée à la base; parcours tactique original.','Choisir une trajectoire avant la fermeture de sa fenêtre; pause et vitesse lente proposées.','Moteur filtré par coque, alarmes brèves et respirations calmes du cockpit.')],
 scenes:[
 S({key:'CONTACT',label:'Contact sur Omega',fact:'Liara et Feron se rencontrent pendant la recherche. ',s:'FERON',ref:'Redemption #1–4, premier contact; pagination à contrôler',theme:'confiance sous pression',objective:'Identifier le bon intermédiaire et atteindre une sortie de quartier.',flow:'Observation → questions → découverte d’un passage → sortie du duo.',rule:'Trois indices locaux proposés renseignent identité, accès et risque; deux suffisent pour avancer, le troisième précise le journal.',choice:'Questionner publiquement ou vérifier discrètement un itinéraire.',choiceRule:'La voie publique réduit la recherche mais augmente les contrôles; la discrétion consomme du temps sans perdre de fait essentiel.',talk:'Liara exprime son urgence; Feron évalue ce qu’il peut révéler.',camera:'Plan d’ensemble du carrefour puis champ rapproché sur les deux silhouettes, sans reproduire les cases.',look:'Alcôve latérale et contre-jour industriel; un ruban lumineux guide la sortie.',sound:'Brouhaha bas et motif de deux notes dissonantes.',prop:['Repère de rendez-vous','Balise de rendez-vous originale.','Éviter une recherche arbitraire dans toute la station.','Inspecter la balise révèle un détail de contexte et un chemin, jamais une position omnisciente.','Plaquette lumineuse usée, symbole simple visible en gros plan.'],effect:'Pulsation douce du repère avec symbole d’enquête, différente d’un objet de combat.',side:['Vérifier une seconde sortie','Cartographier un accès secondaire proposé.','Introduire le rôle prudent de Feron.','Réduit un contrôle local; aucune récompense de lore canon inventée.']}),
 S({key:'AFTERLIFE',label:'Entretien à Afterlife',fact:'Aria intervient dans la recherche du duo. ',s:'FERON',ref:'Redemption, recherche sur Omega',theme:'information conditionnelle',objective:'Obtenir une piste sans transformer l’entretien en recrutement.',flow:'Antichambre → présentation → question ciblée → validation de la piste.',rule:'Le joueur choisit l’ordre des questions; les réponses essentielles restent accessibles sans jauge morale universelle.',choice:'Insister sur l’urgence ou demander d’abord les limites de l’aide.',choiceRule:'Change le ton et un commentaire local; même piste finale.',talk:'Autorité d’Aria, prudence de Feron et volonté de Liara; conserver les intentions sans reprendre les répliques.',camera:'Aria domine le cadre en hauteur; le duo occupe le bas, puis la sortie reprend une caméra jouable.',look:'Fauteuil au fond, foule réduite en silhouettes et trajet libre entre les deux.',sound:'Musique de club originale filtrée durant la conversation.',prop:['Terminal de piste','Fiche de piste originale pour le journal.','Nommer la destination jouable.','Consulter à volonté après l’entretien; ne pas exposer les secrets de Feron.','Écran étroit, zone et objectif en deux lignes.'],effect:'Lueur de confirmation sur le terminal, sans effet de gain de puissance.',side:['Écouter le quartier','Recueillir deux observations ambiantes originales.','Donner du contexte à la station.','Contenu facultatif sans allégation nouvelle sur Aria.']}),
 S({key:'DOCKS',label:'Docks et transfert',fact:'Tazzik supervise le transport du corps de Shepard depuis Omega. ',s:'TAZZIK',ref:'Redemption, transfert sur Omega; numéro à contrôler',theme:'urgence et méfiance',objective:'Traverser une aire de chargement avant la fermeture des accès.',flow:'Repérage des lignes de vue → déplacement couvert → tentative d’interception → poursuite.',rule:'Les caisses fournissent des masques de tir; tirer sur une commande de porte est une option proposée, pas une scène canon.',choice:'Sécuriser le passage du duo ou concentrer les actions sur le contrôle du quai.',choiceRule:'L’une protège le groupe, l’autre raccourcit le trajet; le départ narratif reste fixé.',talk:'Échanger des instructions courtes tout en gardant l’identité des différents employeurs incertaine.',camera:'Glissement latéral révélant le vaisseau; la caméra ne suit pas un projectile hors écran.',look:'Poutres, caisses distinctes du couvert et rampe diagonale.',sound:'Grue, verrou de sas et poussée de moteur.',prop:['Commande de quai','Console originale de verrouillage.','Créer une interaction tactique sans ajouter de technologie canon.','Une action ferme un passage secondaire; le levier principal reste accessible.','Panneau jaune à trois états visibles.'],effect:'Traits de visée arrêtés par les caisses; fermeture de porte annoncée au sol.',side:['Relever la route du cargo','Inspecter un afficheur de départ proposé.','Offrir une aide de navigation pour la scène suivante.','Ajoute un repère visuel, jamais une révélation supplémentaire sur le Courtier.']}),
 S({key:'PURSUIT',label:'Rejoindre la base',fact:'La poursuite du troisième numéro conduit le duo vers la base du Courtier. ',s:'AUTHOR3',ref:'Redemption #3',theme:'dépendance mutuelle',objective:'Choisir une approche compatible avec les contraintes de communication.',flow:'Départ → manœuvres proposées → identification du relais → arrivée.',rule:'Les commandes de route occupent des fenêtres ATB; la prévisualisation montre collision et exposition avant validation.',choice:'Trajectoire courte exposée ou détour abrité.',choiceRule:'Différence de ressources locales; aucune branche vers une autre planète.',talk:'Discuter des risques et de ce que Feron sait du réseau adverse.',camera:'Vue de cockpit simplifiée alternant avec une vue extérieure d’orientation.',look:'Repères de navigation espacés et point de destination fixe.',sound:'Bourdonnement de coque puis silence radio annoncé.',prop:['Afficheur de trajectoire','Outil de navigation original.','Donner une lecture des deux approches.','Prévisualiser un trajet ne dépense aucune action; confirmer l’engage.','Arc de route plein pour la sélection, pointillé pour la prévision.'],effect:'Traînée de route temporaire et masque de brouillage périphérique; pas de flash global.',side:['Calibrer le filtre radio','Réglage facultatif de trois marqueurs proposés.','Aider la lecture des signaux faibles.','Réduit le bruit de l’interface; ne supprime pas la contrainte narrative d’isolement.']}),
 S({key:'ACCESS',label:'Identité et accès compartimentés',fact:'L’auteur relie le cloisonnement de la base aux possibilités d’action de Feron. ',s:'AUTHOR3',ref:'Redemption #3',theme:'apparences et informations',objective:'Franchir deux contrôles locaux sans fournir une carte complète du réseau.',flow:'Sas → contrôle d’identité → relais local → accès au secteur suivant.',rule:'Chaque contrôle demande un type d’information différent; une identité acceptée ne vaut pas accès universel.',choice:'Employer la couverture préparée ou détourner l’attention par une panne locale.',choiceRule:'La couverture conserve l’alerte; la panne ouvre une fenêtre plus courte et attire une patrouille.',talk:'Feron entretient une apparence crédible; Liara doit limiter ses questions au bon moment.',camera:'Cadres fixes derrière les contrôles, visibilité de la sortie maintenue.',look:'Cloisons opaques, câbles de relais et panneaux d’accès individualisés.',sound:'Interphone étouffé et clics d’autorisation.',prop:['Jeton d’accès compartimenté','Objet de gameplay original à portée limitée.','Représenter un droit d’accès sans le confondre avec une clé universelle.','Le jeton n’ouvre que le sas nommé; l’interface annonce cette portée.','Plaquette avec pictogramme du secteur.'],effect:'Deux cadres distincts indiquent identité acceptée et porte accessible.',side:['Relever une anomalie de relais','Comparer deux journaux de connexion proposés.','Montrer les limites du réseau.','Révèle un raccourci local, sans exposer toute l’organisation.']}),
 S({key:'RECOVER',label:'Récupération et séparation',fact:'Le dernier numéro révèle le jeu multiple de Feron. ',s:'AUTHOR4',ref:'Redemption #4',theme:'actes et confiance',objective:'Assurer la récupération dans un espace de sortie sous pression.',flow:'Préparation du duo → fenêtre de transfert → sortie de Liara → raccord narratif.',rule:'La réussite dépend de la synchronisation protection/accès; l’échec propose une reprise locale, pas une fin alternative canon.',choice:'Réserver une action de protection ou neutraliser d’abord un contrôle de quai.',choiceRule:'Change la difficulté de la dernière traversée; la séparation publiée reste un raccord fixe.',talk:'Faire comprendre par actions l’écart entre les paroles et les loyautés de Feron.',camera:'Plan large du hangar, séparation spatiale du duo puis fermeture lente du cadre.',look:'Rampe lumineuse, silhouette du partenaire à distance, conteneur sans visage imposé de Shepard.',sound:'Moteur croissant, communication coupée puis thème inachevé original.',prop:['Support de transfert','Support de transport proposé, sans représentation imposée du visage de Shepard.','Rendre la priorité de mission lisible.','L’objet reste attaché au flux narratif, non vendable et non équipable.','Volume fermé, marquage neutre et témoin d’intégrité abstrait.'],effect:'Ligne de liaison du duo qui s’interrompt au raccord; indication de sortie maintenue.',side:['Préparer une issue de secours','Déverrouiller une sortie secondaire proposée avant le transfert.','Récompenser l’anticipation sans changer la séparation.','Diminue le risque du trajet final; pas de sauvetage canon supplémentaire.']})],
 enemies:[E('SUNS','Blue Suns','Les Blue Suns interviennent contre le duo.','FERON','Pression armée et contrôle du quai.','Armures lourdes bleues à vérifier; casque distinct du personnel neutre.','Alternance fixation et déplacement; contourner un tireur rend sa couverture inutile.','Mise en joue, maintien et recul lisible.','Salves sèches et annonce radio inventée.',[['Fixation de quai','Pattern original de tir soutenu.','Annoncer la ligne de tir; le couvert l’interrompt, déplacement latéral la quitte.','Ligne hachurée au sol.'],['Verrou de passage','Pattern original de contrôle de terrain.','Le mercenaire ferme un accès après préparation; interrompre sa commande ou emprunter l’accès secondaire.','Icône de verrou sur la porte et geste vers le panneau.']]),
 E('SENTRY','Sentries de poursuite','Le wiki décrit des sentries lors de l’approche de la base.','FERON','Menace de navigation proposée, à vérifier dans l’édition.','Petites silhouettes mécaniques différenciées du vaisseau allié.','Préparer une passe puis exposer leur trajectoire; éviter le contact vaut progression.','Virage anticipé et ligne droite de poursuite.','Alerte brève visible dans l’afficheur.',[['Passe de contrôle','Manœuvre de poursuite originale.','Choisir un couloir abrité avant la résolution; aucun tir automatique hors écran.','Arc de balayage.'],['Interception de route','Verrouillage original d’une voie.','Changer de trajectoire pendant la préparation; conserver toujours une issue.','Segment barré avec durée proposée visible.']]),
 E('GUARDS','Gardes de la base','Feron et Liara rencontrent les gardes du Courtier.','FERON','Obstacle de furtivité avant combat.','Silhouettes armées compactes et contraste froid.','Une alerte locale ne propage pas une information impossible sous brouillage.','Contrôle de badge puis pivot de surveillance.','Interphone et signal d’alerte sectoriel.',[['Contrôle rapproché','Inspection originale de couverture.','Présenter un droit adapté ou quitter la zone de contrôle avant son verrouillage.','Cône de question plutôt que viseur mortel.'],['Alerte compartimentée','Renfort original limité au secteur.','Interrompre le relais local; aucun renfort n’apparaît sans entrée visible.','Relais clignotant avec symbole d’appel.']])],
 kit:[K('weapons','SIDEARM','Arme de poing de production','Profil léger proposé pour les confrontations du duo.','Ne pas attribuer un modèle précis sans inspection des cases.','Tir court, précision stable, coût ATB annoncé; couverture réduit la ligne de tir.','Silhouette compacte, canon lisible, palette neutre.','Sortie du holster, visée, recul et rangement.','Le sprite d’arme suit la main et le tir ne traverse pas le couvert.'),K('equipment','ACCESS','Kit de couverture de Feron','Ressource locale originale pour préparer un contrôle.','Matérialiser la préparation d’identité.','Usage limité au secteur préparé; vérifier le coût avant validation.','Petite carte, affichage du secteur en texte.','Inspection à une main et remise en poche.','Impossible d’ouvrir un accès qui n’a pas été préparé.'),K('powers','BIOTIC','Déplacement biotique proposé','Pouvoir tactique original inspiré du rôle de Liara, sans valeur canon.','Créer des fenêtres de traversée.','Sélectionner un objet léger ou une cible compatible; obstacles fixes exclus; coût visible.','Contour cyan et destination marquée.','Bras écartés puis relâchement.','La prévisualisation correspond au résultat et ne déplace pas un objet narratif verrouillé.')]
};

RED.enemies.find(x=>x.key==='SENTRY').s='STORYII';
export const EVO={...common('EVO','Evolution'),title:'Mass Effect: Evolution',sources:sources.EVO,
 scope:'Evolution #1–4 : Première Guerre de Contact, Jack Harper, Arca Monolith, Illium, Palaven et origine de l’Homme trouble. Les récits courts inclus dans certains recueils disposent de leurs catalogues séparés.',
 summary:'Adaptation de production en actes courts : résistance, conséquences d’un contact, confrontation au projet de Desolas et raccord vers une nouvelle identité. Faits éditoriaux brefs; systèmes proposés distincts de la continuité.',
 canonNote:'L’explication exacte des réactions différentes de Jack et Ben n’est pas tranchée par les notes d’auteur. La guerrière Eva Coré ne doit pas être confondue avec la plateforme de ME3 portant ce nom.',
 continuity:'Préquelle de la trilogie. La guerre se termine entre #1 et #2 selon le scénariste; les actes suivants ne prolongent pas artificiellement les hostilités officielles.',
 group:'Jack et Eva forment le groupe de terrain proposé; Ben change de rôle suivant l’ancrage narratif. Saren ne devient pas un équipier permanent.',
 atb:'Coordination de résistance, couverture et perturbation d’artefact; la compréhension de langues est un élément narratif, pas une magie universelle.',
 facts:[{key:'SCOPE',name:'Origine de l’Homme trouble',text:'Le recueil raconte l’origine de l’Homme trouble et réunit Evolution #1–4.',s:'BOOK'},
 {key:'WAR',name:'Frontière entre guerre et après-guerre',text:'Le scénariste situe la fin de la Première Guerre de Contact entre les numéros 1 et 2.',s:'AUTHOR1',ref:'Evolution #1, notes de fabrication'},
 {key:'CONTACT',name:'Contact direct et indirect',text:'Ben touche directement le Monolithe; Jack le touche par son intermédiaire. L’auteur laisse leur différence de réaction incertaine.',s:'AUTHOR3',ref:'Evolution #3',adapt:'Ne pas convertir cette hypothèse en règle biologique certaine.'},
 {key:'META',name:'Dénomination Meta-turian',text:'Le scénariste explique avoir nommé les turiens transformés « Meta-turians ».',s:'AUTHOR4',ref:'Evolution #4',adapt:'Utiliser une famille visuelle distincte, sans inventer une nouvelle espèce autonome.'}],
 actors:[A('JACK','Jack Harper','Jack Harper est au centre de l’origine présentée.','AUTHOR2','Chef de petit groupe; lecture d’indices et décision tactique.','Humain de terrain, veste simple et posture attentive; yeux et transformations à contrôler.','Observation, appui au couvert et hésitation après une perception.',['Lecture d’ouverture','Proposition : observer une action ennemie pour révéler sa prochaine zone; ne donne pas accès aux pensées.','Icône d’œil et zone prévue en pointillés.']),
 A('EVA','Eva Coré','Eva accompagne Jack et Ben.','EVA','Partenaire de combat mobile; soutien de la progression.','Tenue de résistance fonctionnelle, silhouette agile; éviter le design du robot de ME3.','Glissade au couvert, geste d’arrêt et tir d’appui.',['Appui croisé','Une action réserve une fenêtre de couverture à Jack; celle-ci expire s’il change de secteur.','Deux lignes de visée courtes et une zone de passage.']),
 A('BEN','Ben Hislop','Ben subit une transformation au contact de l’Arca Monolith.','AUTHOR3','Personnage à états narratifs distincts; aucune guérison facultative non sourcée.','Deux silhouettes de production séparées, humaine et transformée; détails organiques à contrôler.','État humain souple, état transformé raide et déplacements orientés vers l’artefact.',null),
 A('DESOLAS','Desolas Arterius','Desolas recherche le pouvoir associé aux traditions et à l’artefact.','AUTHOR3','Antagoniste militaire et idéologique; autorité sur le terrain.','Turien à silhouette de commandement, éléments cérémoniels à vérifier.','Gestes mesurés, présentation publique et recul lorsque le contrôle se rompt.',null),
 A('SAREN','Saren Arterius','Saren apparaît dans le deuxième numéro comme frère de Desolas.','AUTHOR2','Interlocuteur dont les intérêts ne sont pas ceux du groupe.','Armure turienne antérieure à ME1, sans ajouter ses implants ultérieurs par défaut.','Regard latéral, maintien de l’arme et intervention ciblée.',null,{cat:'npcs'}),
 A('ABRUDAS','Lieutenant Abrudas','L’auteur identifie Abrudas comme la première turienne montrée dans ces comics.','AUTHOR1','PNJ militaire de la période; contrôler le design historique.','Silhouette turienne féminine issue de la référence BioWare évoquée par l’auteur; aucune reconstruction anatomique affirmée.','Ordre bref, surveillance et réaction au danger.',null,{cat:'npcs'}),
 A('WILLIAMS','Général Williams','Le général Williams apparaît; sa décision de démissionner est montrée au numéro 2.','AUTHOR2','Repère politique de l’après-guerre.','Uniforme sobre et silhouette d’officier; insignes à comparer.','Écoute assise, remise d’un document et départ.',null,{cat:'npcs'})],
 worlds:[W('SHANXI','Shanxi','Eva participe à la résistance sur Shanxi occupée.','EVA','Premier acte militaire localisé.','Rue couverte, angle de patrouille et approche d’une cavité; aucun champ de bataille global simulé.','Relief rocheux visible au-delà des structures.','Roche poussiéreuse, métal terne et lumière rasante.','Raccord d’une embuscade proposée vers la zone de l’artefact.','Patrouilles annoncées; civils exclus des cibles automatiques.','Vent sec et communications militaires fragmentées.'),
 W('ARCTURUS','Arcturus Station','Le deuxième numéro visite Arcturus Station.','AUTHOR2','Intermède d’après-guerre et prise d’information.','Salle d’attente, bureau et belvédère reliés par un passage sûr.','Vue extérieure de la station depuis une baie.','Blanc cassé, bleu froid, surfaces ordonnées et éclairage sans clignotement.','Entrée après la fin de guerre, sortie vers Illium; pas de retour déclenchant de nouvelles batailles.','Pas de combat obligatoire dans le hub.','Ventilation stable, pas réguliers et annonces de service originales.'),
 W('ILLIUM','Illium','Illium apparaît au deuxième numéro.','AUTHOR2','Enquête dans un contexte étranger.','Aire de transit et espace industriel à accès progressif.','Façades verticales derrière un quai de service.','Verre sombre, métal poli et accents ambrés.','Transit → piste → espace de confrontation; liaisons originales à échelle réduite.','Contrôles d’accès et lignes de vue, sans marché ouvert inventé.','Circulation aérienne lointaine et moteurs industriels.'),
 W('PALAVEN','Palaven','Palaven est un cadre important du troisième numéro.','AUTHOR3','Mettre en scène tradition militaire et instrumentalisations de l’artefact.','Approche cérémonielle, galerie et salle d’artefact connectées par un itinéraire clair.','Verticalité de l’édifice et emplacement central du Monolithe.','Volumes minéraux monumentaux, éclairage oblique et métal froid.','Accès contrôlé puis sortie de crise; aucune exploration globale de la planète.','Zones d’influence proposées autour de l’artefact; limites affichées.','Résonances sourdes, pas de foule scandant des slogans reproduits.')],
 scenes:[
 S({key:'RESIST',label:'Résistance sur Shanxi',fact:'Le premier numéro se déroule pendant la Première Guerre de Contact. ',s:'AUTHOR1',ref:'Evolution #1',theme:'ignorance de l’autre',objective:'Franchir un secteur surveillé avec un petit groupe.',flow:'Observation → préparation → passage couvert → regroupement.',rule:'Une action d’appui ouvre une traversée; une alarme déplace les patrouilles sans créer un ennemi infini.',choice:'Contourner la patrouille ou l’immobiliser momentanément.',choiceRule:'Détour plus long contre consommation d’un outil; le groupe rejoint le même ancrage.',talk:'Employer des informations partielles sur l’adversaire, sans exposer tout le lore des jeux futurs.',camera:'Plan bas sur les silhouettes de résistance, puis vue d’ensemble du passage.',look:'Muret cassé, poussière basse et entrée de cavité lisible.',sound:'Vent et bruits de matériel; musique originale à pulsation retenue.',prop:['Balise de regroupement','Balise de production originale.','Rendre visible le point de ralliement.','Active après traversée du premier personnage; n’attire pas automatiquement la patrouille.','Lumière fixe occultable.'],effect:'Trait discontinu reliant les couverts utilisables.',side:['Observer le cycle de patrouille','Relever deux passages adverses proposés.','Récompenser la préparation.','Affiche les prochains déplacements sans rendre les adversaires inertes.']}),
 S({key:'MONOLITH',label:'Proximité de l’Arca Monolith',fact:'L’Arca Monolith est l’artefact central commenté par l’auteur. ',s:'AUTHOR1',ref:'Evolution #1',theme:'curiosité et exposition',objective:'Approcher l’objet selon des étapes de mise en scène contrôlées.',flow:'Entrée → observation à distance → événement de contact fixé → évacuation.',rule:'Les interactions facultatives décrivent des perceptions; elles ne changent ni l’exposition publiée ni l’origine des personnages.',choice:'Examiner l’environnement ou sécuriser d’abord la sortie.',choiceRule:'Une option donne un repère supplémentaire, l’autre facilite l’évacuation; aucun remède ajouté.',talk:'Questions sur ce que le groupe comprend réellement; conserver l’incertitude scientifique.',camera:'Silhouette de l’objet tenue au centre, visages en réaction plutôt qu’exposé explicatif.',look:'Masse verticale sombre, contours lumineux retenus et lumière du sol.',sound:'Basse sourde progressive doublée d’un signal visuel.',prop:['Sonde de distance','Outil d’observation original, non preuve d’un dispositif source.','Permettre l’examen sans longue exposition de texte.','Donne des lectures contradictoires annoncées comme telles.','Écran minimal avec trois bandes qualitatives.'],effect:'Ondulation locale sans flash plein écran; pause de lecture disponible.',side:['Marquer l’issue de la cavité','Poser un repère de sortie proposé.','Aider l’évacuation.','Ne permet pas d’éviter l’événement canon de contact.']}),
 S({key:'AFTERWAR',label:'Après la guerre',fact:'Le deuxième numéro se situe après la fin des hostilités. ',s:'AUTHOR1',ref:'Transition Evolution #1 → #2',theme:'victoire incomplète',objective:'Comprendre le changement de contexte avant de quitter la station.',flow:'Annonce de contexte → conversation → bilan du groupe → départ.',rule:'Enquête sans chronomètre; les indices décrivent les conséquences, pas un objectif d’élimination.',choice:'Demander d’abord le bilan militaire ou la situation personnelle.',choiceRule:'Modifie l’ordre des informations et le ton; toutes restent consultables.',talk:'Williams et le groupe peuvent exprimer des buts divergents sans devenir des factions de réputation arbitraires.',camera:'Plan stable sur le bureau, puis ouverture vers le départ.',look:'Ordre institutionnel contrastant avec le matériel abîmé du groupe.',sound:'Ambiance de station calme, thème incomplet de Jack.',prop:['Dossier de transition','Résumé original des informations déjà établies.','Séparer ce que le joueur sait des perceptions de Jack.','Les nouveaux faits restent marqués source ou hypothèse.','Deux colonnes nommées observation et interprétation.'],effect:'Ligne de frise passant explicitement de guerre à après-guerre.',side:['Reconstituer le matériel perdu','Liste facultative de matériel proposé.','Préparer les choix tactiques suivants.','Aucun objet secret ou arme unique canon ajouté.']}),
 S({key:'ILLIUM',label:'Piste sur Illium',fact:'Le deuxième numéro introduit Illium et Saren dans cet arc. ',s:'AUTHOR2',ref:'Evolution #2',theme:'poursuite et terrain inconnu',objective:'Suivre une piste jusqu’à un accès industriel.',flow:'Transit → collecte d’observations → contrôle d’accès → confrontation raccordée.',rule:'Deux routes proposent lecture sociale ou détour technique; chacune fournit la même destination.',choice:'Contacter un intermédiaire original ou inspecter le trajet de livraison.',choiceRule:'Le contact coûte une ressource locale; le trajet expose à un contrôle évitable.',talk:'Jack distingue les signes nouveaux qu’il perçoit de ce qu’il peut expliquer.',camera:'Vue d’ensemble verticale, puis resserrement dans la zone de service.',look:'Façade brillante, couloir de service mat et lignes de livraison au sol.',sound:'Trafic distant et outils de manutention.',prop:['Manifeste de livraison','Document de mission original.','Donner une destination sans inventer un commerce officiel.','Comparer symbole et horaire révèle le bon accès.','Texte bref et deux pictogrammes concordants.'],effect:'Correspondance des symboles par encadrement, lisible sans couleur.',side:['Vérifier l’issue industrielle','Inspection facultative d’une porte de service.','Offrir une issue tactique.','Ne modifie pas la présence de Saren ni le raccord de l’arc.']}),
 S({key:'PALAVEN',label:'Tradition et projet de Desolas',fact:'Le troisième numéro montre Desolas utiliser les traditions de Palaven pour son projet. ',s:'AUTHOR3',ref:'Evolution #3',theme:'autorité instrumentalisée',objective:'Traverser une installation dont les accès suivent un ordre cérémoniel proposé.',flow:'Observation de l’espace → compréhension des contrôles → passage → confrontation.',rule:'L’ordre des accès est un puzzle original de signalétique, pas une liturgie turienne canon inventée.',choice:'Exploiter le protocole local ou chercher une voie technique.',choiceRule:'Le protocole exige une observation, la voie technique une préparation; toutes deux convergent.',talk:'Opposer les promesses de puissance aux signes de perte de contrôle sans long discours copié.',camera:'La hauteur de Desolas domine d’abord, puis le cadre révèle l’artefact derrière lui.',look:'Piliers, galerie surélevée et axe visuel vers le Monolithe.',sound:'Réverbération profonde et motif martial original qui se désaccorde.',prop:['Panneau de protocole','Signalétique de production inventée.','Rendre le puzzle compréhensible sans codex massif.','Trois formes donnent l’ordre d’activation; texte alternatif disponible.','Plaques minérales contrastées.'],effect:'Désalignement progressif des halos de contrôle, avec symbole de perte de liaison.',side:['Identifier une zone refuge','Repérer une alcôve protégée proposée.','Préparer la sortie de crise.','Aucun personnage supplémentaire à sauver comme fait officiel.']}),
 S({key:'BREAK',label:'Rupture du contrôle',fact:'L’auteur décrit l’artefact comme le moyen de contrôle des êtres transformés et la cause de la chute de Desolas. ',s:'AUTHOR4',ref:'Evolution #4',theme:'limites de la domination',objective:'Ouvrir une fenêtre de sortie pendant la rupture du dispositif.',flow:'Menace accrue → coordination du groupe → événement narratif fixé → sortie et épilogue.',rule:'Le combat proposé porte sur la survie locale; détruire toutes les unités n’est pas une condition et ne change pas la fin.',choice:'Dégager le chemin ou réduire la pression du groupe adverse.',choiceRule:'Les méthodes modifient l’effort de sortie; aucun sauvetage alternatif de Ben ou Eva n’est présenté comme canon.',talk:'Faire entendre les désaccords entre Saren et Desolas par des intentions nouvelles, sans réécrire leur issue.',camera:'Plan large sur la rupture, puis cadre serré sur Jack isolé.',look:'Fissures de lumière périphériques, silhouettes séparées du fond.',sound:'Rupture de basse, silence de respiration puis nouveau motif original.',prop:['Commande de sortie de crise','Interaction de production proposée.','Donner un objectif lisible pendant le chaos.','N’active que les accès de fuite; ne contrôle pas l’Arca Monolith.','Panneau mécaniquement simple et lisible.'],effect:'Les liens de contrôle proposés se rompent en traits courts, sans éclats stroboscopiques.',side:['Préparer le chemin de repli','Retirer un obstacle mobile proposé.','Permettre une sortie plus fluide.','Ne change pas le bilan publié; récompense seulement la préparation locale.']})],
 enemies:[E('PATROL','Patrouille turienne','La résistance humaine affronte des forces turiennes sur Shanxi.','EVA','Adversaire militaire local.','Armures de guerre de la période à contrôler, silhouettes angulaires.','Cohésion de patrouille avec couverture mutuelle, pas une représentation de tous les turiens.','Arrêt au signal, visée collective et rotation de garde.','Ordres inventés brefs.',[['Balayage synchronisé','Pattern original de surveillance.','Observer le cône puis traverser dans l’intervalle; une diversion ne fonctionne qu’une fois.','Cônes alternés.'],['Couverture de camarade','Pattern original défensif.','Le garde protège un allié jusqu’à son prochain déplacement; contourner la ligne protège le joueur.','Trait de liaison entre les deux gardes.']]),
 E('META','Meta-turiens','Les notes du dernier numéro nomment les turiens transformés.','AUTHOR4','Famille hostile liée au contrôle de l’artefact.','Turien rigidifié, zones lumineuses localisées; détails de transformation à vérifier.','Avance vers le signal central; perte de liaison crée une fenêtre d’évitement proposée.','Posture rigide, pas lourds et arrêt simultané.','Pulsations métalliques doublées d’un pictogramme.',[['Marche au signal','Pattern original de pression.','Une zone de charge est annoncée; se décaler avant la résolution évite l’impact.','Bande rectiligne au sol.'],['Retour à l’artefact','Pattern original de repli.','L’unité retourne au nœud après interruption; exploiter ce trajet, sans prétendre guérir la transformation.','Flèche vers le nœud.']]),
 E('BENMETA','Ben transformé — rencontre proposée','La transformation de Ben est explicitement commentée par l’auteur.','AUTHOR3','Confrontation émotionnelle avec objectif de survie.','Silhouette humaine transformée, posture distincte des Meta-turiens.','Ne pas traiter sa santé comme une solution à son destin; objectif de passage local.','Fixation sur l’artefact et geste brusque télégraphié.','Souffle filtré et motif de reconnaissance original.',[['Rejet de proximité','Attaque originale de zone.','S’écarter du cercle annoncé ou protéger le partenaire.','Cercle hachuré sans couleur obligatoire.'],['Fixation monolithique','Comportement original d’exposition.','Après une poussée, la cible se tourne vers l’artefact et laisse une sortie; aucune faiblesse canon universelle déduite.','Orientation visible de la tête et du torse.']])],
 kit:[K('weapons','RIFLE','Fusil de résistance proposé','Profil de fusil contemporain de la scène à choisir après référence visuelle.','Combat couvert pour le groupe humain.','Rafale courte puis récupération; pas de marque ou de cadence canon ajoutée.','Arme sobre, contour compact, munitions non détaillées.','Épaulé, recul et retour au couvert.','Le modèle ne réutilise pas automatiquement une arme de ME3.'),K('equipment','SCANNER','Sonde d’observation limitée','Outil original de distance et de lecture.','Soutenir l’enquête sans expliquer tout l’artefact.','Affiche des indices qualitatifs, jamais une mesure scientifique canon inventée.','Trois bandes et pictogramme d’incertitude.','Déploiement bref et lecture.','Toute conclusion incertaine est marquée hypothèse.'),K('powers','PERCEPTION','Perception de Jack — traduction proposée','L’auteur évoque de nouvelles capacités, dont des langues auparavant inconnues; leur règle jouable reste proposée.','Débloquer une lecture ponctuelle de signe.','Utilisable seulement aux points préparés par le récit; ne devient ni télépathie ni piratage universel.','Encart de perception distinct de la traduction normale.','Fixation, réaction puis retour au groupe.','L’interface distingue perception, interprétation et fait confirmé.')]
};

export const INV={...common('INV','Invasion'),title:'Mass Effect: Invasion',sources:sources.INV,
 scope:'Invasion #1–4 : défense d’Omega, menace des Adjutants, alliance circonstancielle, Avernus et prise de pouvoir de Cerberus. Le DLC Omega reste un raccord, pas un cinquième numéro.',
 summary:'Spécifications originales pour une défense de station, une coopération instable et une sortie imposée par la menace stratégique. Le catalogue distingue l’ennemi publié des règles de contagion et de combat proposées.',
 canonNote:'Les règles de propagation et de transformation jouables sont des abstractions originales. Ne pas confondre les Adjutants de cet arc avec tous leurs comportements du DLC Omega.',
 continuity:'L’arc prépare la situation d’Omega dans ME3; le scénariste décrit explicitement le DLC Omega comme suite. Aria quitte la station dans le final.',
 guard:'Conserver le raccord d’occupation d’Omega et le départ d’Aria; une victoire tactique locale ne permet pas de gagner une guerre contraire au comic.',
 group:'Aria dirige un groupe local proposé; les soutiens de Cerberus sont temporaires et changent de disponibilité selon la phase.',
 atb:'Défense de couloirs, extraction et contrôle d’exposition; le temps de combat se suspend pendant les décisions stratégiques.',
 facts:[{key:'SCOPE',name:'Omega au centre du conflit',text:'Aria défend Omega face à une menace liée à Cerberus.',s:'BOOK'},
 {key:'FINAL',name:'Raccord du dernier numéro',text:'Le scénariste confirme la fuite d’Aria et les doutes de Petrovsky au dernier numéro.',s:'AUTHOR4',ref:'Invasion #4'},
 {key:'DLC',name:'Suite dans Omega',text:'L’auteur présente le DLC Omega comme la suite de cet arc.',s:'AUTHOR4',ref:'Notes d’Invasion #4'},
 {key:'GANGS',name:'Coopération des gangs',text:'Le scénariste souligne la coopération des gangs visible dans leurs tactiques et armes au final.',s:'AUTHOR4',ref:'Invasion #4'}],
 actors:[A('ARIA','Aria T’Loak','Aria gouverne Omega et défend la station.','BOOK','Cheffe de groupe; contrôle d’espace et ordres de repli.','Silhouette asari tendue, veste de combat et accents violets; tenue à vérifier.','Appui ferme, poussée large, geste d’ordre et recul contrôlé.',['Repli sous pression','Proposition : réserver une action qui protège la traversée d’un allié entre deux couverts; ne soigne pas une infection.','Couloir de retrait bordé d’un contour violet et d’un symbole de bouclier.']),
 A('PETROVSKY','Oleg Petrovsky','Petrovsky commande les opérations de Cerberus contre Omega.','PETROVSKY','Allié circonstanciel puis adversaire stratégique; décisions à distance.','Officier humain au port formel, uniforme clair/sombre et décor de passerelle.','Observation d’une carte, ordre bref et mains jointes.',null),
 A('ASHE','Raymond Ashe','Ashe est associé à Petrovsky dans l’opération.','PETROVSKY','Figure de pression militaire, distincte de la prudence du général.','Officier plus anguleux et posture avancée; grades exacts à contrôler.','Pointage énergique, mouvement brusque et activation d’un panneau.',null),
 A('TIM','L’Homme trouble','Cerberus est la force politique derrière la menace sur Omega.','BOOK','Interlocuteur distant; garder son information hors de la connaissance du joueur.','Hologramme à fort contre-jour et visage calme.','Immobile, interruption du signal et reprise mesurée.',null,{cat:'npcs'}),
 A('DEFENDERS','Défenseurs d’Omega','Les gangs coopèrent dans la défense décrite au final.','AUTHOR4','Soutien collectif original; rôles limités à la station.','Armures et espèces variées, brassard de rôle temporaire inventé.','Port de matériel, couverture et appel au repli.',['Tenir le passage','Une réserve de soutien retarde un groupe hostile sur un seul accès; afficher clairement qu’elle est temporaire.','Pictogramme du passage et barre de préparation proposée.'])],
 worlds:[W('OMEGA','Omega','Omega est l’enjeu principal de l’arc.','BOOK','Défense de territoire et de routes de repli.','Trois couloirs connectés à une place refuge; éviter une carte trop vaste pour les sprites.','Vue sur le noyau industriel et silhouette d’Afterlife.','Métal noirci, lumière ambre et zones de danger à hachures.','Quai → secteurs civils → centre de commandement; accès ferment selon la phase.','La progression privilégie l’extraction et le passage, pas l’élimination d’une foule entière.','Alarmes sectorielles, coque qui travaille et annonces de repli originales.'),
 W('ELBRUS','Elbrus','Le wiki identifie l’Elbrus comme le vaisseau de Petrovsky.','PETROVSKY','Passerelle de coopération temporaire.','Carte centrale, baie d’observation et console de liaison.','La carte de la station reste le point focal.','Gris militaire, blanc directionnel et écrans lisibles.','Embarquement narratif vers une opération limitée; accès bloqué après rupture d’alliance.','Pas de libre achat d’armes dans un vaisseau allié de circonstance.','Basse de moteur stable et messages tactiques filtrés.'),
 W('AVERNUS','Avernus Station','Avernus est liée aux Adjutants dans le récit rapporté.','ADJ','Faire comprendre la source d’une crise sans une encyclopédie complète.','Sas, salle de contrôle et aire isolée à circulation en boucle.','Vitrage brisé et canal technique vers la zone suivante.','Surfaces froides, matériel de recherche abandonné et balises de confinement.','Entrée depuis l’opération, contrôle local puis départ; aucune exploration scientifique illimitée.','Exposition représentée par pression locale proposée; ne pas inventer un traitement canon.','Ventilation interrompue, contacts métalliques et silence entre alarmes.'),
 W('AFTERLIFE','Afterlife','Le wiki situe une confrontation importante à Afterlife.','PETROVSKY','Retour à un lieu de pouvoir devenu piège.','Salle principale, balcon et deux accès visibles.','Fauteuil et scène centrale comme silhouette de pouvoir.','Néons atténués, débris au sol hors trajet et lumière coupée par secteurs.','Accès de retour puis sortie d’exil; pas de restauration immédiate du hub.','La fermeture d’un accès est toujours annoncée avant résolution.','Ancienne pulsation de club filtrée, alarmes et thème suspendu.')],
 scenes:[
 S({key:'BREACH',label:'Alerte sur les quais',fact:'Le récit décrit des Adjutants libérés par un transport sur Omega. ',s:'ADJ',ref:'Invasion, attaque initiale; numéro à contrôler',theme:'rupture du quotidien',objective:'Sécuriser une voie de retrait vers un secteur protégé.',flow:'Alerte → identification de la menace → défense d’accès → repli.',rule:'Le groupe protège des sorties avec une réserve de pression; les corps ne deviennent pas automatiquement des unités supplémentaires sans signal.',choice:'Verrouiller un accès ou extraire d’abord les personnes visibles.',choiceRule:'Modifier le placement et le risque local; aucun total officiel de victimes n’est inventé.',talk:'Aria donne des instructions claires; les témoins ne connaissent pas encore la nature complète de l’attaque.',camera:'Départ serré sur une activité de quai, ouverture sur la rupture du périmètre.',look:'Transport en silhouette, rangées de caisses et sortie refuge éclairée.',sound:'Clang de rampe puis alarme localisée.',prop:['Verrou de quai','Commande de confinement proposée.','Offrir une action de terrain compréhensible.','La porte bloque le passage mais peut retenir un allié; prévisualiser les positions avant fermeture.','Panneau à état ouvert/fermé avec silhouette de passage.'],effect:'Bord de menace hachuré qui progresse par segments, sans simulation médicale.',side:['Guider un groupe de dockers','Extraction originale de figurants anonymes.','Mettre en valeur l’enjeu civil sans ajouter de héros canon.','Facultatif; le compteur décrit uniquement la simulation locale.']}),
 S({key:'ALLIANCE',label:'Coordination de circonstance',fact:'Petrovsky et Aria coopèrent face à la menace initiale. ',s:'PETROVSKY',ref:'Invasion, coopération initiale',theme:'intérêts incompatibles',objective:'Préparer une action conjointe en gardant les objectifs distincts.',flow:'Briefing → affectation de deux soutiens → défense → réévaluation.',rule:'Chaque soutien indique sa portée et sa durée; l’alliance n’accorde ni confiance définitive ni recrutement de Petrovsky.',choice:'Demander un soutien de tir ou un soutien de transport.',choiceRule:'Le premier protège un couloir, le second raccourcit un trajet d’extraction; les deux ont une seule fenêtre proposée.',talk:'Présenter l’intérêt partagé et les lignes rouges d’Aria sans révéler tous les plans de Cerberus.',camera:'Carte de la station entre les interlocuteurs; changement de cadre lorsque le joueur choisit une route.',look:'Carte nette sur fond militaire dépouillé.',sound:'Ordres brefs et moteur grave régulier.',prop:['Carte de coordination','Interface stratégique originale.','Comparer les deux soutiens.','Afficher portée, délai proposé et incompatibilité avant confirmation.','Deux routes et pictogrammes de soutien, aucune statistique prétendue officielle.'],effect:'Traits distincts pour forces locales et Cerberus, avec motifs non fondés seulement sur la couleur.',side:['Confirmer une voie de secours','Vérifier une route alternative originale.','Limiter une surprise de navigation.','Révèle la sortie sur la carte sans modifier la décision adverse.']}),
 S({key:'AVERNUS',label:'Confinement à Avernus',fact:'Le récit rapporte une opération à Avernus Station liée aux Adjutants. ',s:'ADJ',ref:'Invasion, opération à Avernus',theme:'cause et responsabilité',objective:'Traverser le secteur de confinement et activer une issue opérationnelle.',flow:'Sas → lecture des risques → action sur contrôle → départ.',rule:'Trois secteurs proposés s’isolent séparément; aucun bouton ne guérit ou ne supprime tous les Adjutants de l’univers.',choice:'Isoler un secteur ou détourner son alimentation.',choiceRule:'Isolation réduit la mobilité, alimentation déplace le danger; sortie finale commune.',talk:'Questions sur les expériences et sur l’urgence, en distinguant faits vus et explications des officiers.',camera:'Largeur du couloir visible, caméra de contrôle séparée de la zone hostile.',look:'Baies froides, grilles et panneaux de confinement lisibles.',sound:'Pulsation de ventilation qui s’arrête après chaque fermeture.',prop:['Contrôle sectoriel','Panneau original de confinement.','Rendre les conséquences de chaque option visibles.','Confirmer seulement après prévisualisation du groupe; avertir si un allié serait isolé.','Schéma de trois compartiments et état textuel.'],effect:'Lumière de joint et carte des compartiments fermés, sans particules opaques.',side:['Copier un état de confinement','Rapport technique original limité à la scène.','Expliquer les contraintes du niveau.','N’ajoute aucune conclusion canon sur l’origine des créatures.']}),
 S({key:'RETURN',label:'Retour dans une station contestée',fact:'La défense d’Omega se transforme en conflit avec Cerberus. ',s:'BOOK',ref:'Invasion #1–4, retournement du conflit',theme:'territoire perdu',objective:'Réunir les défenseurs et rejoindre un point de communication.',flow:'Constat → choix de route → défense mobile → contact.',rule:'La carte change d’accès, pas de coordonnées arbitraires; les routes connues deviennent des risques lisibles.',choice:'Passer par un ancien poste de garde ou par une route industrielle.',choiceRule:'Poste : affrontement bref; route : interaction technique sous menace. Même destination.',talk:'Aria coordonne sans prétendre contrôler chaque faction; les soutiens expriment leurs limites.',camera:'Reprendre un point de vue déjà vu pour montrer le changement d’occupation.',look:'Nouveaux checkpoints superposés au décor initial sans le reconstruire entièrement.',sound:'Radio militaire au premier plan et ancienne ambiance étouffée.',prop:['Plan local annoté','Carte originale d’accès désormais fermés.','Éviter de perdre le joueur après le changement de phase.','Les anciens accès restent dessinés mais barrés avec une raison.','Traits pleins, pointillés et étiquettes courtes.'],effect:'Marquage d’occupation qui ne masque pas les sorties.',side:['Récupérer un émetteur local','Objectif facultatif original.','Permettre un appel de soutien supplémentaire limité.','L’émetteur n’annule pas l’avantage stratégique adverse.']}),
 S({key:'TRAP',label:'Piège d’Afterlife',fact:'Le wiki décrit un piège impliquant Ashe et un Adjutant à Afterlife. ',s:'PETROVSKY',ref:'Invasion, confrontation finale; contrôler le découpage',theme:'coût de l’escalade',objective:'Dégager les lignes de sortie pendant une confrontation concentrée.',flow:'Entrée → fermeture annoncée → menace de zone → issue narrative.',rule:'Le danger se lit par cônes et trajectoires; l’attaque de zone peut être évitée par placement, pas par un temps de réaction minuscule.',choice:'Éloigner la menace du passage ou protéger d’abord un soutien.',choiceRule:'Change l’ordre des actions et les ressources locales; ne réécrit pas le destin d’Ashe.',talk:'Divergence de méthodes entre commandants; ne pas transformer les propos adverses en vérité du journal.',camera:'Vue large sur les deux accès, gros plan seulement après résolution du danger.',look:'Centre dégagé et balcon servant de repère.',sound:'Coupe de la musique, mouvement lourd et alarmes brèves.',prop:['Barrière de scène','Obstacle mobile original du prototype.','Créer une séparation tactique sans changer l’architecture canon.','Déplacer une seule fois; ne peut bloquer les deux sorties.','Masse basse à bord clair.'],effect:'Trajectoire de projection en pointillés, point d’impact marqué avant confirmation.',side:['Préparer le passage arrière','Ouverture facultative originale.','Réduire le nombre d’actions du repli.','Le piège narratif reste déclenché au même ancrage.']}),
 S({key:'EXILE',label:'Ultimatum et départ',fact:'Le dernier numéro se conclut par le départ d’Aria. ',s:'AUTHOR4',ref:'Invasion #4',theme:'survivre à une défaite stratégique',objective:'Organiser une sortie sans promettre une victoire impossible dans cet arc.',flow:'Constat stratégique → décisions de préparation → départ fixé → raccord ME3.',rule:'Les choix portent sur l’ordre de préparation et les ressources locales conservées; aucune option ne détruit la flotte adverse.',choice:'Prioriser le matériel d’information ou la préparation des soutiens.',choiceRule:'Variante locale de journal et d’inventaire de simulation; même départ canon.',talk:'Aria conserve une intention de retour; Petrovsky reste un adversaire dont les doutes ne font pas un allié.',camera:'Éloignement de la station, silhouette d’Aria immobile puis extinction du contrôle.',look:'Omega en arrière-plan, palette refroidie et espace négatif devant le personnage.',sound:'Thème original interrompu, moteur lent et silence de fin.',prop:['Liste de départ','Outil de préparation original.','Afficher ce qui sera conservé dans le module.','Les objets narratifs obligatoires sont verrouillés contre la vente et l’oubli.','Cases simples avec statut transporté/non nécessaire.'],effect:'La carte d’Omega change d’état d’occupation; aucune explosion ajoutée comme fin alternative.',side:['Archiver les itinéraires connus','Tâche originale de mémoire de carte.','Préparer un lien documentaire vers le futur DLC.','Ne débloque pas la reconquête dans ce classeur.']})],
 enemies:[E('ADJ','Adjutant','Les Adjutants constituent la menace de l’attaque d’Omega.','ADJ','Pression rapprochée et contrôle d’exposition.','Corps massif et asymétrique à comparer aux planches; articulation lisible.','Exposition abstraite proposée; avertissement avant tout changement d’état et reprise locale en cas d’échec.','Préparation ramassée, bond lisible et récupération lourde.','Grondement original avec pictogramme de menace.',[['Bond de contamination — proposition','Pattern original de saut de zone.','Marquer la zone puis laisser une action de déplacement; une protection interrompt seulement le contact local.','Cercle hachuré et corps accroupi.'],['Pression de proximité — proposition','Zone de danger originale.','Quitter le voisinage ou repousser avant saturation; aucune jauge n’est une mesure biologique canon.','Anneau segmenté et état textuel exposition.']]),
 E('CERBERUS','Forces de Cerberus','Cerberus cherche à prendre Omega.','BOOK','Opposition militaire structurée.','Armures blanches et sombres à vérifier; silhouette distincte des gangs.','Couverture et contrôle d’accès; les renforts empruntent une porte visible.','Appui au couvert et changement de position annoncé.','Radio filtrée et tirs courts.',[['Couloir interdit','Pattern original de suppression.','Couvert ou interruption de l’opérateur rompt la ligne; la zone ne traverse pas les murs.','Bande au sol avec symbole de tir.'],['Avancée en binôme','Pattern original de progression.','Une unité se déplace pendant que l’autre couvre; exploiter le changement de rôle.','Deux marqueurs reliés.']]),
 E('BOARDING','Équipe de contrôle du quai — proposition','Un groupe tactique original représente la pression d’occupation dans le prototype.',null,'Rencontre locale ajoutée, pas unité nommée officielle.','Silhouettes militaires génériques sans insigne de régiment inventé.','Ouvre/ferme un accès selon une préparation visible; la neutralisation n’inverse pas l’occupation.', 'Geste vers la console, maintien puis déplacement.','Verrou de porte et confirmation radio originale.',[['Fermeture de sas','Action originale de terrain.','Interrompre la commande ou choisir la sortie secondaire avant fermeture.','Panneau et porte clignotent en alternance.'],['Inspection de refuge','Pression originale sur une zone.','Évacuer les figurants visibles ou détourner le groupe; pas de bilan civil officiel calculé.','Cône de recherche et symbole refuge.']],{nature:'Extrapolation'})],
 kit:[K('weapons','OMEGA','Armement de défense local','Profils d’armes à choisir après référence visuelle des gangs.','Différencier tir de suppression et tir précis.','Deux profils proposés; coût ATB et portée affichés, aucune marque canon ajoutée.','Armes usées de silhouettes différentes.','Visée, recul court et changement de couvert.','Chaque profil a un usage distinct et une contre-mesure visible.'),K('equipment','BARRIER','Dispositif de fermeture locale','Équipement de terrain original du prototype.','Isoler un couloir pour un repli.','Pose sur ancrages autorisés; refus explicite si elle bloquerait toute sortie.','Boîtier et lignes de fermeture sobres.','Pose, activation et retrait.','La navigation du groupe reste valide après activation.'),K('powers','ARIA','Projection biotique proposée d’Aria','Commande de contrôle originale liée à son rôle.','Créer une fenêtre de repli.','Projeter une cible compatible vers un emplacement libre; prévisualiser la trajectoire et protéger les zones civiles.','Arc violet doublé d’une flèche.','Ancrage des pieds, geste large et retour.','Aucune cible n’est projetée à travers un mur ni hors de la carte.'),K('equipment','EXPOSURE','Indicateur d’exposition abstrait','Interface de combat originale, sans valeur médicale canon.','Rendre la menace compréhensible.','Trois états qualitatifs proposés : libre, exposé, critique; récupération uniquement selon les règles du scénario.','Icône segmentée plus texte.','Transition douce entre états.','Le joueur voit la cause de chaque changement et les moyens de prévention.')]
};
